#include "ctforge.h"

struct ctforge_config ctforged_config;

/*
 * ctforge-lsiggen - sign the light-skeleton loader blob of a payload
 * module.
 *
 * A light skeleton generated by "bpftool -L gen skeleton" embeds two
 * byte arrays in the module skel header: opts_insn (the loader
 * program instructions) and opts_data (the loader data blob holding
 * map definitions, payload program instructions and initial values).
 * Together they are the loader blob, and they are the only BPF
 * content shipped by a loader-mode module.
 *
 * This tool extracts both arrays from the generated header, builds
 * the loader blob (instructions first, then data), signs it with the
 * module SM2 private key and emits a C source file defining
 * ctforge_get_loader_sig() for the module .so. The runtime twin of
 * this check is verify_loader_sig() in libbpf's skel_internal.h,
 * which rejects unsigned loader blobs before anything reaches the
 * kernel.
 *
 * Usage:
 *   ctforge-lsiggen -k private.pem -K public.pem \
 *                   -i module_skel.h -o module_lskel_sig.c
 */

#define MAX_BLOB_SIZE	(64 * 1024 * 1024)

static void usage(const char *prog)
{
	pr_err("Usage: %s -k private.pem -K public.pem -i input_skel.h -o output_sig.c",
	       prog);
}

static int hex_val(char c)
{
	if (c >= '0' && c <= '9')
		return c - '0';
	if (c >= 'a' && c <= 'f')
		return c - 'a' + 10;
	if (c >= 'A' && c <= 'F')
		return c - 'A' + 10;
	return -1;
}

/*
 * Decode one byte-array string literal emitted by bpftool's
 * print_hex(): every byte is either \xHH or \0, and long literals
 * are wrapped with backslash-newline continuations. Returns a
 * malloc'ed buffer holding the array content.
 */
static unsigned char *decode_skel_array(const char *hdr, const char *name,
					size_t *out_len)
{
	unsigned char *buf, *p;
	const char *cur, *pat;
	size_t buf_len = 0;

	/* try dedicated array form first: "name[]" */
	{
		char name_pat[64];
		snprintf(name_pat, sizeof(name_pat), "%s[]", name);
		pat = strstr(hdr, name_pat);
	}
	/* fall back to inline field: "<name> = (void *)\"" */
	if (!pat) {
		char field_pat[64];
		snprintf(field_pat, sizeof(field_pat), "%s = (void *)\"", name);
		pat = strstr(hdr, field_pat);
	}
	if (!pat) {
		pr_err("array/field %s not found in skeleton header", name);
		return NULL;
	}

	/* skip array attributes up to the '=' that starts the
	 * initializer, then jump to the opening quote of the literal
	 */
	cur = strchr(pat, '=');
	if (!cur) {
		pr_err("malformed declaration of %s", name);
		return NULL;
	}
	cur = strchr(cur, '"');
	if (!cur) {
		pr_err("missing string literal for %s", name);
		return NULL;
	}
	cur++;

	{
		/* find the real end (to closing quote, not NUL) */
		const char *end = cur;
		while (*end && *end != '"') end++;
		size_t raw_len = end - cur;
		buf = malloc(raw_len + 1);
	}
	if (!buf) {
		pr_err("out of memory");
		return NULL;
	}
	p = buf;

	while (*cur && *cur != '"') {
		if (*cur != '\\') {
			pr_err("unexpected byte 0x%02x in %s literal",
			       (unsigned char)*cur, name);
			goto err_free;
		}
		cur++;

		switch (*cur) {
		case 'x': {
			int hi, lo;

			hi = hex_val(*(cur + 1));
			lo = hex_val(*(cur + 2));
			if (hi < 0 || lo < 0) {
				pr_err("malformed \\x escape in %s", name);
				goto err_free;
			}
			*p++ = (hi << 4) | lo;
			cur += 3;
			break;
		}
		case '0':
			*p++ = 0;
			cur++;
			break;
		case '\n':
			/* backslash-newline line continuation */
			cur++;
			break;
		default:
			pr_err("unsupported escape \\%c in %s", *cur, name);
			goto err_free;
		}

		if ((size_t)(p - buf) > MAX_BLOB_SIZE) {
			pr_err("%s literal exceeds %d bytes", name,
			       MAX_BLOB_SIZE);
			goto err_free;
		}
	}

	if (*cur != '"') {
		pr_err("unterminated %s literal", name);
		goto err_free;
	}

	*out_len = (size_t)(p - buf);
	return buf;

err_free:
	free(buf);
	return NULL;
}

static int emit_sig_source(const char *out_path, const unsigned char *sig,
			   size_t sig_len)
{
	FILE *f;
	size_t i;

	f = fopen(out_path, "w");
	if (!f) {
		pr_err("cannot open %s for writing", out_path);
		return -1;
	}

	fprintf(f, "/* Auto-generated by ctforge-lsiggen. Do not edit.\n");
	fprintf(f, " *\n");
	fprintf(f, " * SM2 signature over the light-skeleton loader blob of\n");
	fprintf(f, " * this module: loader instructions first, then the\n");
	fprintf(f, " * loader data blob.\n");
	fprintf(f, " */\n");
	fprintf(f, "#include <stddef.h>\n\n");
	fprintf(f, "static const unsigned char ctforge_loader_sig[]\n");
	fprintf(f, "\t__attribute__((__aligned__(8))) = {\n");

	for (i = 0; i < sig_len; i++) {
		if (i % 12 == 0)
			fprintf(f, "\t");
		fprintf(f, "0x%02x", sig[i]);
		if (i + 1 < sig_len)
			fprintf(f, ", ");
		if ((i + 1) % 12 == 0 || i + 1 == sig_len)
			fprintf(f, "\n");
	}

	fprintf(f, "};\n\n");
	fprintf(f, "__attribute__((visibility(\"hidden\")))\n");
	fprintf(f, "const unsigned char *ctforge_get_loader_sig(size_t *len)\n");
	fprintf(f, "{\n");
	fprintf(f, "\t*len = sizeof(ctforge_loader_sig);\n");
	fprintf(f, "\treturn ctforge_loader_sig;\n");
	fprintf(f, "}\n");

	if (fclose(f) != 0) {
		pr_err("failed to write %s", out_path);
		return -1;
	}
	return 0;
}

int main(int argc, char **argv)
{
	unsigned char *hdr = NULL, *insns = NULL, *data = NULL;
	unsigned char *blob = NULL, *sig = NULL;
	const char *priv_path = NULL, *pub_path = NULL;
	const char *in_path = NULL, *out_path = NULL;
	size_t hdr_len = 0, insns_len = 0, data_len = 0;
	size_t sig_len = 0, blob_len;
	int opt, ret = -1;

	while ((opt = getopt(argc, argv, "k:K:i:o:")) != -1) {
		switch (opt) {
		case 'k':
			priv_path = optarg;
			break;
		case 'K':
			pub_path = optarg;
			break;
		case 'i':
			in_path = optarg;
			break;
		case 'o':
			out_path = optarg;
			break;
		default:
			usage(argv[0]);
			return -1;
		}
	}

	if (!priv_path || !pub_path || !in_path || !out_path) {
		usage(argv[0]);
		return -1;
	}

	hdr = load_file((char *)in_path, &hdr_len);
	if (!hdr) {
		pr_err("cannot read skeleton header %s", in_path);
		goto out;
	}

	insns = decode_skel_array((const char *)hdr, "insns",
				  &insns_len);
	if (!insns)
		goto out;

	data = decode_skel_array((const char *)hdr, "data",
				 &data_len);
	if (!data)
		goto out;

	/* the loader blob is instructions followed by data */
	blob_len = insns_len + data_len;
	blob = malloc(blob_len);
	if (!blob) {
		pr_err("out of memory");
		goto out;
	}
	memcpy(blob, insns, insns_len);
	memcpy(blob + insns_len, data, data_len);

	ret = sm2_sign((const char *)blob, blob_len, priv_path,
		       &sig, &sig_len);
	if (ret != 0) {
		pr_err("sign loader blob failed: %d", ret);
		ret = -1;
		goto out;
	}

	/* self check with the public key so a wrong key fails the build */
	ret = sm2_verify((const char *)blob, blob_len, pub_path,
			 sig, sig_len);
	if (ret != 0) {
		pr_err("self verification of loader signature failed: %d", ret);
		ret = -1;
		goto out;
	}

	ret = emit_sig_source(out_path, sig, sig_len);
	if (ret == 0)
		pr_info("loader blob %zu bytes, signature %zu bytes written to %s",
			blob_len, sig_len, out_path);

out:
	free(hdr);
	free(insns);
	free(data);
	free(blob);
	free(sig);
	return ret;
}
